"""capsule_emit.produce returns the same bytes as Go and TypeScript.

Two shared sources prove it:

* ``go/testdata/capsule-emit/format4-interop-v05`` is the pack Go
  (``format4_interop_test.go``) and TypeScript (``ts/test/interop.test.ts``)
  replay byte-for-byte: seal with model and runtime, received, WHO/DID seals
  and a WHO/CAN/DID composition given out of order.
* ``go/testdata/produce-cross-check`` is generated by Go
  (``produce_cross_check_test.go``) from ``input.json`` and covers what that
  pack does not: build with every optional member, carry, received, sealing
  explicit JSON null, compositions with AUDIT and runtime, digest_json values,
  timestamp normalization, and inputs both implementations must reject.
"""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import pytest

from capsule_emit import produce as p

GO_TESTDATA = Path(__file__).resolve().parents[2] / "go" / "testdata"
INTEROP = GO_TESTDATA / "capsule-emit" / "format4-interop-v05"
CROSS_CHECK = GO_TESTDATA / "produce-cross-check"
# Rejections whose message wording differs between Go and Python: the API
# names (SealInput.Model vs model, Seal vs seal), the upstream canonicalizer's
# number errors, and Go's "built payload failed" prefix on Class 1 failures.
_MESSAGES_DIFFER = {
    "seal_composition_with_payload",
    "seal_float_payload",
    "seal_unsafe_integer_output",
    "seal_model_on_capsule",
    "witnessed_without_corroboration",
    # Text from different canonicalizers and JSON decoders.
    "reference_log_coordinates_float",
    "extension_trailing_value",
}


def _identity(seed_hex: str) -> p.SigningIdentity:
    return p.new_ed25519_signing_identity(bytes.fromhex(seed_hex))


# ---------------------------------------------------------------------------
# format4-interop-v05


def _interop_spec() -> dict[str, Any]:
    return json.loads((INTEROP / "input.json").read_text(encoding="utf-8"))


def _replay_interop() -> dict[str, p.Result]:
    spec = _interop_spec()
    identity = _identity(spec["seed_hex"])
    disposition = spec["disposition"]
    slots = {"who": p.who, "can": p.can, "did": p.did, "audit": p.audit}
    results: dict[str, p.Result] = {}
    for record in spec["records"]:
        capsule = p.Input(
            action_id=record["action_id"],
            action_type=record["action_type"],
            operator=spec["operator"],
            developer=spec["developer"],
            timestamp=spec["timestamp"],
            disposition=p.Disposition(
                decision=disposition["decision"],
                approver=disposition["approver"],
                human_disposed=disposition["human_disposed"],
                verdict_class=record["verdict"],
            ),
        )
        operation = record["operation"]
        if operation == "seal":
            model = record.get("model")
            result = p.seal(
                p.SealInput(
                    capsule=capsule,
                    identity=identity,
                    payload=record.get("payload"),
                    agent_output=record.get("agent_output"),
                    model=p.Model(provider=model["provider"], model_id=model["model_id"]) if model else None,
                    runtime=record.get("runtime", ""),
                )
            )
        elif operation == "received":
            built = p.received(capsule, record["artifact_utf8"].encode("utf-8"), record["artifact_type"])
            result = p.Result(capsule_id=built.capsule_id, payload=built.json, envelope=p.sign(built, identity))
        else:
            assert operation == "composition"
            members = [slots[m["slot"]](results[m["record"]]) for m in record["members"]]
            result = p.seal(p.SealInput(capsule=capsule, identity=identity, members=members))
        results[record["name"]] = result
    return results


def test_format4_interop_v05_byte_identical():
    results = _replay_interop()
    assert list(results) == ["authored", "received", "who", "did", "composition"]
    for name, result in results.items():
        case = INTEROP / "valid" / name
        expected = json.loads((case / "expected.json").read_text(encoding="utf-8"))
        assert result.capsule_id == expected["capsule_id"], name
        assert result.payload == (case / "capsule.detached.jcs").read_bytes(), name
        assert result.envelope == (case / "envelope.cose").read_bytes(), name
        verified = p.verify_envelope(result.capsule_id, result.envelope)
        assert verified.public_key.hex() == expected["public_key_hex"]
        stored = (case / "capsule.stored.json").read_bytes()
        assert p.verify_capsule(stored).ok
        value = p.decode_payload(stored)
        assert value["capsule_id"] == result.capsule_id
        assert value["signature"] == result.envelope.hex()
        assert value["spec_version"] == p.SPEC_VERSION


# ---------------------------------------------------------------------------
# produce-cross-check (Go-generated)


def _reference(raw: dict[str, Any]) -> p.Reference:
    return p.Reference(
        type=raw.get("type", ""),
        digest_alg=raw.get("digest_alg", ""),
        digest=raw.get("digest", ""),
        citation_purpose=raw.get("citation_purpose", ""),
        log_coordinates=raw.get("log_coordinates"),
    )


def _input(raw: dict[str, Any]) -> p.Input:
    """Mirror of Go's crossCheckInput.toInput."""
    def opt(key, factory):
        return factory(raw[key]) if raw.get(key) is not None else None

    provenance_mode = None
    if raw.get("provenance_mode") is not None:
        mode = raw["provenance_mode"]
        provenance_mode = p.ProvenanceMode(
            mode=mode.get("mode", ""),
            source_ref=_reference(mode["source_ref"]) if mode.get("source_ref") is not None else None,
            source_asserted_at=mode.get("source_asserted_at", ""),
            import_batch=mode.get("import_batch", ""),
            imported_at=mode.get("imported_at", ""),
            time_rung=mode.get("time_rung", ""),
        )
    return p.Input(
        action_id=raw.get("action_id", ""),
        action_type=raw.get("action_type", ""),
        operator=raw.get("operator", ""),
        developer=raw.get("developer", ""),
        timestamp=raw.get("timestamp", ""),
        epoch_id=raw.get("epoch_id", ""),
        domain=raw.get("domain", ""),
        provenance=raw.get("provenance", ""),
        disposition=opt("disposition", lambda d: p.Disposition(
            decision=d.get("decision", ""),
            approver=d.get("approver", ""),
            human_disposed=d.get("human_disposed", False),
            verdict_class=d.get("verdict_class", ""),
            reason_digest=d.get("reason_digest", ""),
        )),
        effect=opt("effect", lambda e: p.Effect(
            type=e.get("type", ""),
            status=e.get("status", ""),
            irreversibility_class=e.get("irreversibility_class", ""),
            effect_attestation=e.get("effect_attestation", ""),
            request_digest=e.get("request_digest", ""),
            response_digest=e.get("response_digest", ""),
            external_ref=e.get("external_ref", ""),
        )),
        chain=opt("chain", lambda c: p.Chain(parent_capsule_id=c.get("parent_capsule_id", ""), relation=c.get("relation", ""))),
        references=opt("references", lambda refs: [_reference(r) for r in refs]),
        model=opt("model", lambda m: p.Model(provider=m.get("provider", ""), model_id=m.get("model_id", ""))),
        compute=opt("compute", lambda c: p.ComputeAttestation(
            agent_input_digest=c.get("agent_input_digest", ""),
            agent_output_digest=c.get("agent_output_digest", ""),
            runtime=c.get("runtime", ""),
        )),
        provenance_mode=provenance_mode,
        extensions=[_extension(x) for x in raw.get("extensions", [])],
    )


def _extension(raw: dict[str, Any]) -> p.Extension:
    # value_text is exact JSON text a JSON document cannot hold (empty,
    # trailing data, a repeated member name); value is any JSON value.
    text = raw["value_text"] if "value_text" in raw else json.dumps(raw["value"])
    return p.Extension(name=raw["name"], value=text)


def _artifact(record: dict[str, Any]) -> bytes:
    if "artifact_hex" in record:
        return bytes.fromhex(record["artifact_hex"])
    return record["artifact_utf8"].encode("utf-8")


def _seal_value(record: dict[str, Any], key: str) -> Any:
    if record.get(key + "_null"):
        return p.JSON_NULL
    return record.get(key)


def _run(record: dict[str, Any], identity: p.SigningIdentity, prior: dict[str, p.Result]) -> p.Result:
    """Mirror of Go's runCrossCheckRecord."""
    capsule = _input(record["input"])
    operation = record["operation"]
    slots = {"who": p.who, "can": p.can, "did": p.did, "audit": p.audit}
    members = [slots[m["slot"]](prior[m["record"]]) for m in record.get("members", [])]
    if operation == "seal":
        model = record.get("model")
        return p.seal(
            p.SealInput(
                capsule=capsule,
                identity=identity,
                payload=_seal_value(record, "payload"),
                agent_output=_seal_value(record, "agent_output"),
                model=p.Model(provider=model.get("provider", ""), model_id=model.get("model_id", "")) if model else None,
                runtime=record.get("runtime", ""),
                members=members if "members" in record else None,
            )
        )
    if operation == "build":
        built = p.build(capsule)
    elif operation == "carry":
        built = p.carry(capsule, _artifact(record))
    elif operation == "received":
        built = p.received(capsule, _artifact(record), record["artifact_type"])
    elif operation == "composition":
        built = p.build_composition(capsule, *members)
    else:  # pragma: no cover - fixture defect
        raise AssertionError(f"unsupported operation {operation}")
    return p.Result(capsule_id=built.capsule_id, payload=built.json, envelope=p.sign(built, identity))


def _cross_check():
    spec = json.loads((CROSS_CHECK / "input.json").read_text(encoding="utf-8"))
    expected = json.loads((CROSS_CHECK / "expected.json").read_text(encoding="utf-8"))
    return spec, expected


def test_cross_check_records_byte_identical_to_go():
    spec, expected = _cross_check()
    identity = _identity(spec["seed_hex"])
    assert identity.public_key.hex() == expected["public_key_hex"]
    prior: dict[str, p.Result] = {}
    want = {r["name"]: r for r in expected["records"]}
    assert list(want) == [r["name"] for r in spec["records"]]
    for record in spec["records"]:
        result = _run(record, identity, prior)
        prior[record["name"]] = result
        go = want[record["name"]]
        assert result.capsule_id == go["capsule_id"], record["name"]
        assert result.payload.decode("utf-8") == go["capsule_jcs"], record["name"]
        assert result.envelope.hex() == go["envelope_hex"], record["name"]
    assert len(prior) >= 10


def test_cross_check_digests_match_go():
    spec, expected = _cross_check()
    want = {d["name"]: d["digest"] for d in expected["digests"]}
    assert set(want) == {d["name"] for d in spec["digests"]}
    for case in spec["digests"]:
        assert p.digest_json(case["value"]) == want[case["name"]], case["name"]


def test_cross_check_timestamps_match_go():
    spec, expected = _cross_check()
    want = {t["input"]: t["wire"] for t in expected["timestamps"]}
    assert set(want) == set(spec["timestamps"])
    for text in spec["timestamps"]:
        assert p.format_timestamp(text) == want[text], text


def test_cross_check_rejections_match_go():
    spec, expected = _cross_check()
    assert [r["name"] for r in expected["rejections"]] == [r["name"] for r in spec["rejections"]]
    identity = _identity(spec["seed_hex"])
    prior: dict[str, p.Result] = {}
    for record in spec["records"]:
        prior[record["name"]] = _run(record, identity, prior)
    go_errors = {r["name"]: r["error"] for r in expected["rejections"]}
    differing = {}
    for record in spec["rejections"]:
        with pytest.raises((ValueError, TypeError)) as caught:
            _run(record, identity, prior)
        if str(caught.value) != go_errors[record["name"]]:
            differing[record["name"]] = str(caught.value)
    # Both reject every case; the message is Go's word for word except where
    # the wording names the language-specific API or comes from a different
    # upstream canonicalizer.
    assert set(differing) == _MESSAGES_DIFFER, differing
